const items = $input.all();

// Escape text so spreadsheet values display safely inside HTML.
const escapeHtml = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

// Clean spreadsheet values.
const clean = (value) =>
  value == null ? '' : String(value).trim().replace(/\s+/g, ' ');

// Format the fee status consistently.
const formatStatus = (value) => {
  const status = clean(value).toLowerCase();

  if (['yes', 'paid', 'true', '1'].includes(status)) return 'Paid';
  if (['no', 'unpaid', 'false', '0'].includes(status)) return 'Not Paid';

  return status
    ? status.charAt(0).toUpperCase() + status.slice(1)
    : 'Not Provided';
};

// Clean and prepare student records.
const students = items
  .map(item => ({
    id: clean(item.json.Student_ID),
    name: clean(item.json.Name),
    course: clean(item.json.Course),
    status: formatStatus(item.json.Fee_Paid)
  }))
  .filter(student => student.id || student.name || student.course);

// Avoid sending an email when there are no usable records.
if (students.length === 0) {
  return [{
    json: {
      hasData: false,
      subject: 'Student Data Summary',
      body: '<p>No student records were found.</p>'
    }
  }];
}

// Create one table row per student.
const tableRows = students.map((student, index) => `
  <tr>
    <td style="padding:12px;border-bottom:1px solid #e5e7eb;color:#64748b;">
      ${index + 1}
    </td>
    <td style="padding:12px;border-bottom:1px solid #e5e7eb;">
      ${escapeHtml(student.name || 'Not Provided')}
    </td>
    <td style="padding:12px;border-bottom:1px solid #e5e7eb;">
      ${escapeHtml(student.course || 'Not Provided')}
    </td>
    <td style="padding:12px;border-bottom:1px solid #e5e7eb;">
      <span style="font-weight:600;">
        ${escapeHtml(student.status)}
      </span>
    </td>
  </tr>
`).join('');

// Build a structured HTML email.
const body = `
<div style="font-family:Arial,Helvetica,sans-serif;color:#1f2937;line-height:1.6;max-width:800px;margin:0 auto;">
  <div style="background:#f3f6fb;padding:24px;border-radius:8px 8px 0 0;">
    <h2 style="margin:0;color:#1d4ed8;">Student Data Summary</h2>
    <p style="margin:8px 0 0;color:#4b5563;">
      Here is the latest data retrieved from Google Sheets.
    </p>
  </div>

  <div style="padding:20px;border:1px solid #e5e7eb;border-top:0;">
    <p>Hello,</p>
    <p>Please find the student records below.</p>

    <p style="background:#eff6ff;padding:12px;border-radius:6px;">
      <strong>Total student records:</strong> ${students.length}
    </p>

    <table style="width:100%;border-collapse:collapse;font-size:14px;text-align:left;">
      <thead>
        <tr style="background:#1d4ed8;color:#ffffff;">
          <th style="padding:12px;">#</th>
          <th style="padding:12px;">Name</th>
          <th style="padding:12px;">Course</th>
          <th style="padding:12px;">Status</th>
        </tr>
      </thead>
      <tbody>
        ${tableRows}
      </tbody>
    </table>

    <p style="margin-top:24px;">Regards,<br><strong>Your Automation Bot</strong></p>
  </div>
  <p style="font-size:12px;color:#6b7280;text-align:center;margin-top:16px;">
    This email was automatically generated by n8n.
  </p>
</div>
`;

return [{
  json: {
    subject: `Student Data Summary - ${students.length} Records`,
    body,
    hasData: true,
    totalStudents: students.length
  }
}];
